/**
 * scripts/verify_build_artifacts.js
 * Inspects prerendered HTML output and module code generated by next build.
 */

const fs = require('fs');
const path = require('path');

let passed = 0;
let failed = 0;

function assert(condition, testName, detail = '') {
  if (condition) {
    console.log(`✅ PASS: ${testName}`);
    passed++;
  } else {
    console.error(`❌ FAIL: ${testName}${detail ? ` -> ${detail}` : ''}`);
    failed++;
  }
}

console.log('================================================================');
console.log('🔍 VERIFYING NEXT.JS COMPILED ARTIFACTS & HTML PRERENDERS');
console.log('================================================================\n');

// 1. Verify index.html (Public Homepage)
console.log('--- 1. Prerendered Homepage (.next/server/app/index.html) ---');
const indexPath = path.join(__dirname, '..', '.next', 'server', 'app', 'index.html');
assert(fs.existsSync(indexPath), 'index.html exists');

if (fs.existsSync(indexPath)) {
  const html = fs.readFileSync(indexPath, 'utf8');
  assert(html.includes('Start Learning'), 'Contains "Start Learning" central CTA');
  assert(html.includes('href="/auth"'), '"Start Learning" navigates to /auth');
  assert(!html.includes('Enrol now') && !html.includes('Enrol Now') && !html.includes('Enrol for free'), 'Zero occurrences of "Enrol now" / "Enrol for free" in prerendered HTML');
  assert(!html.includes('Personal email') && !html.includes('placeholder="Personal email"'), 'Zero occurrences of "Personal email" input field');
  assert(!html.includes('href="/create"'), 'Dashboard preview "+ New Course" button is non-interactive (no /create link)');
}

// 2. Verify auth.html (Authentication Page)
console.log('\n--- 2. Prerendered Auth Page (.next/server/app/auth.html) ---');
const authPath = path.join(__dirname, '..', '.next', 'server', 'app', 'auth.html');
assert(fs.existsSync(authPath), 'auth.html exists');

if (fs.existsSync(authPath)) {
  const html = fs.readFileSync(authPath, 'utf8');
  assert(html.includes('Notionwell'), 'Auth page contains Notionwell branding');
  assert(!html.includes('http-equiv="refresh"'), 'No meta-refresh redirect tag in auth.html');
}

// 3. Verify demo.html (Guest Demo Page)
console.log('\n--- 3. Prerendered Demo Page (.next/server/app/demo.html) ---');
const demoPath = path.join(__dirname, '..', '.next', 'server', 'app', 'demo.html');
assert(fs.existsSync(demoPath), 'demo.html exists');

if (fs.existsSync(demoPath)) {
  const html = fs.readFileSync(demoPath, 'utf8');
  assert(html.includes('Computer Networks'), 'Demo page includes "Computer Networks"');
}

// 4. Verify viva.html (AI Viva Page)
console.log('\n--- 4. Prerendered Viva Page (.next/server/app/viva.html) ---');
const vivaPath = path.join(__dirname, '..', '.next', 'server', 'app', 'viva.html');
assert(fs.existsSync(vivaPath), 'viva.html exists');

// 5. Verify source code unit checks
console.log('\n--- 5. Source Unit Logic Audits ---');
const appTs = fs.readFileSync(path.join(__dirname, '..', 'lib', 'app.ts'), 'utf8');
assert(!appTs.includes('const storedAcc = getStoredAccount();') || !appTs.includes('return { isLoggedIn: true, loggedInEmail: storedAcc.email };'), 'getSession() does not restore unverified stored accounts without active session');
assert(appTs.includes('await signOutUserFromSupabase()'), 'logoutUser() explicitly awaits signOutUserFromSupabase()');

const authTs = fs.readFileSync(path.join(__dirname, '..', 'lib', 'supabase', 'auth.ts'), 'utf8');
assert(authTs.includes("signOut({ scope: 'local' })"), 'signOutUserFromSupabase executes local signOut');
assert(authTs.includes('localStorage.removeItem(\'notionwell_session_v1\')'), 'signOutUserFromSupabase cleans up session tokens');

const authPage = fs.readFileSync(path.join(__dirname, '..', 'app', 'auth', 'page.tsx'), 'utf8');
assert(authPage.includes('supabase.auth.getSession()'), 'app/auth/page.tsx queries getSession() first to avoid premature redirect');

console.log('\n================================================================');
console.log(`🏁 VERIFICATION SUMMARY: ${passed} PASSED, ${failed} FAILED`);
console.log('================================================================');

if (failed > 0) process.exit(1);
